// 1. Captura a resposta da API (acessando a primeira posição do array retornado)
const resposta = $input.first().json;

// Busca o array de faturas dentro do campo 'dados'
const faturas = resposta.dados || [];

// VERIFICAÇÃO: Se a API retornou sucesso = false ou se a lista de dados veio vazia
if (resposta.sucesso === false || faturas.length === 0) {
  return {
    texto_final: "📄 *CONSULTA DE FATURAS*\n━━━━━━━━━━━━━━━━━━\n\nNenhuma fatura pendente foi encontrada no seu cadastro no momento. ✅\n\n━━━━━━━━━━━━━━━━━━\n_Deseja consultar outra coisa? Digite *0* para voltar ao menu._",
    faturas_mapeadas: [],
    nenhum_boleto: true
  };
}

// 2. Formata a lista e mapeia para o Redis
let listaFormatada = "📄 *FATURAS ENCONTRADAS*\n━━━━━━━━━━━━━━━━━━\n\n";
let faturasMapeadas = [];

faturas.forEach((item, index) => {
  const opcao = index + 1; 

  // Trata a data de vencimento no padrão ISO da nova API
  const dataFormatada = new Date(item.vencimento).toLocaleDateString('pt-BR', { timeZone: 'UTC' });

  // Formata o valor numérico para Moeda Real (BRL)
  const valorFormatado = item.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  listaFormatada += `${opcao}️⃣ *Boleto:* ${item.numeroDocumento}\n`;
  listaFormatada += `📅 *Vencimento:* ${dataFormatada}\n`;
  listaFormatada += `💵 *Valor:* ${valorFormatado}\n`;
  listaFormatada += `📝 *Descrição:* ${item.descricao || 'Fatura em aberto'}\n\n`;

  // Guarda no mapeamento para o Redis usar na hora de baixar o PDF selecionado
  faturasMapeadas.push({
    indice: opcao,
    boleto_id: item.idBoleto, 
    numero_boleto: item.numeroDocumento
  });
});

listaFormatada += "━━━━━━━━━━━━━━━━━━\n";


return {
  texto_final: listaFormatada,
  faturas_mapeadas: faturasMapeadas,
  nenhum_boleto: false
};

