// 1. CAPTURA FIXA DO MERGE
const dadosMerge = $('Merge1').first().json.dados_sessao;

let estadoAuth = 'inicio';
let menuAtual = '';

try {
  const sessaoObjeto = typeof dadosMerge === 'string'
    ? JSON.parse(dadosMerge)
    : (dadosMerge || {});

  estadoAuth = sessaoObjeto?.auth?.estado_anterior || 'inicio';
  menuAtual = sessaoObjeto?.navegacao?.menu_atual ?? '';
} catch (e) {
  estadoAuth = 'inicio';
  menuAtual = '';
}

// Prioridade: mensagem contextual gerada pelo menu3 no fallback de menu
let menu3Data = null;
try {
  menu3Data = $('menu3').first().json;
  if (menu3Data?.rota_destino === 'fallback' && menu3Data?.mensagem_texto) {
    return [{
      json: {
        texto_erro: menu3Data.mensagem_texto,
        estado_validado: estadoAuth,
        menu_validado: menuAtual
      }
    }];
  }
} catch (e) {}

const menuPrincipalMsg = `*MENU PRINCIPAL* 👋\n━━━━━━━━━━━━━━━━━━\nComo posso te ajudar hoje?\n\n1️⃣ - *Minhas faturas*\n2️⃣ - *Meus CCR* (Comprovantes)\n3️⃣ - *MTR* (Manifestos)\n4️⃣ - *Meus contratos*\n9️⃣ - *Falar com atendente*\n\n━━━━━━━━━━━━━━━━━━\n💡 _Digite *Sair* para encerrar o atendimento._`;

const menuCCRMsg = `📦 *MEUS COMPROVANTES (CCR)*\n━━━━━━━━━━━━━━━━━━\nComo deseja visualizar suas últimas coletas?\n\n1️⃣ - *Último CCR*\n2️⃣ - *Últimos 3 CCRs*\n3️⃣ - *Últimos 6 CCRs*\n\n━━━━━━━━━━━━━━━━━━\n9️⃣ - *Falar com atendente*\n0️⃣ - *Voltar ao menu anterior*`;

const menuBuscarCCRMsg = `📦 *CCRs DISPONÍVEIS*\n━━━━━━━━━━━━━━━━━━\nComo deseja receber?\n\n1️⃣ - Último CCR\n2️⃣ - Últimos 3 CCRs\n3️⃣ - Últimos 6 CCRs\n━━━━━━━━━━━━━━━━━━\n\n9️⃣ - *Falar com atendente*\n0️⃣ - *Voltar ao menu*`;

const menuBoletoMsg = `📄 Digite o *número da opção* (1, 2, 3...) para receber o PDF da fatura desejada.\n\n━━━━━━━━━━━━━━━━━━\n9️⃣ - *Falar com atendente*\n0️⃣ - *Voltar ao menu*`;

let mensagem = '';

if (estadoAuth === 'cliente_novo' || (menuAtual === '' && estadoAuth !== 'autenticado_autorizado')) {
  mensagem = 'Ops! 😕 Não consegui compreender sua resposta.\n\nPor favor, responda apenas *1* para SIM ou *2* para NÃO para nos informar se você já possui cadastro conosco.';
} else if (estadoAuth === 'autorizado') {
  mensagem = '⚠️ Opção inválida.\n\nPor favor, digite apenas *1* se deseja confirmar a validação dos seus dados ou *2* caso queira cancelar.';
} else if (estadoAuth === 'AGUARDANDO_CPF') {
  mensagem = 'Desculpe, o CPF ou CNPJ informado não foi localizado em nosso sistema ou está inconsistente. ⚠️\n\nPor favor, certifique-se de enviar *apenas os números* do documento cadastrado na plataforma.';
} else if (estadoAuth === 'AGUARDANDO_CONFIRMAR') {
  mensagem = '🔒 *Confirmação de Segurança*\n\nO dado informado não confere com o CPF do responsável pela empresa.\n\nPor favor, digite apenas os *4 primeiros dígitos* do CPF do titular do cadastro para liberar o acesso.';
} else if (menuAtual === 'selecione_boleto') {
  mensagem = `⚠️ *Opção inválida.*\n\n${menuBoletoMsg}`;
} else if (menuAtual === 'buscar_ccr') {
  mensagem = `⚠️ *Opção inválida.*\n\n${menuBuscarCCRMsg}`;
} else if (menuAtual === 'Meus_CCR' || menuAtual === 'nenu_ccr') {
  mensagem = `⚠️ *Opção inválida.*\n\n${menuCCRMsg}`;
} else if (menuAtual === 'Menu_Principal' || estadoAuth === 'autenticado_autorizado') {
  mensagem = `⚠️ *Opção inválida.*\n\n${menuPrincipalMsg}`;
} else if (menuAtual === 'fluxo_finalizado') {
  mensagem = '⚠️ *Opção inválida.*\n\nDigite *1* para voltar ao menu principal ou *2* para falar com atendente.';
} else if (estadoAuth === 'token_invalido' || estadoAuth === 'TOKEN_EXPIRADO') {
  mensagem = '⚠️ *SESSÃO EXPIRADA*\n━━━━━━━━━━━━━━━━━━\n\nSua sessão de segurança expirou por tempo limite. ⏳\n\nPor favor, envie qualquer mensagem de texto para reiniciar o seu processo de identificação.';
} else {
  mensagem = 'Poxa, não consegui localizar essa opção no menu. 🤔\n\nPor favor, envie apenas o *número* correspondente à opção desejada ou digite *Sair* a qualquer momento para finalizar.';
}

return [{
  json: {
    texto_erro: mensagem,
    estado_validado: estadoAuth,
    menu_validado: menuAtual
  }
}];

